def f(inp):
    H,W=len(inp),len(inp[0])
    out=[r[:] for r in inp]
    # find zero rows and zero cols (separators)
    zrows=[i for i,r in enumerate(inp) if all(x==0 for x in r)]
    zcols=[j for j in range(W) if all(r[j]==0 for r in inp)]
    zr=[i for i in range(H) if i not in zrows]; zc=[j for j in range(W) if j not in zcols]
    # group contiguous
    def groups(ids):
        gs=[];cur=[]
        for i in ids:
            if cur and i==cur[-1]+1: cur.append(i)
            else: if cur: gs.append(cur); cur=[i]
        if cur: gs.append(cur)
        return gs
    rgs=groups(zr); cgs=groups(zc)
    for rs in rgs:
        for cs in cgs:
            blk={(r,c) for r in rs for c in cs}
            d=min(inp[r][c] for r,c in blk if inp[r][c]!=0)
            for r,c in blk: out[r][c]=d+5
    return out

